	private static boolean contains(Throwable failure, Throwable expected, Set<Throwable> visited) {
		if (failure == expected) {
			return true;
		}
		if (failure == null || !visited.add(failure)) {
			return false;
		}
		if (contains(failure.getCause(), expected, visited)) {
			return true;
		}
		for (Throwable suppressed : failure.getSuppressed()) {
			if (contains(suppressed, expected, visited)) {
				return true;
			}
		}
		return false;
	}
